  `cust_smsno` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_ci DEFAULT '0',
  `cust_partygroup` int DEFAULT '0',
  `cust_noof_visits1` int DEFAULT '0',
  `cust_desp_target1` int DEFAULT '0',
  `cust_payperf1` decimal(6,2) DEFAULT '0.00',
  `cust_tcs_applied` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_ci DEFAULT 'Y',
